<script>
import { Passkeys, UserCancelledError } from '@laravel/passkeys';
import { router } from '@inertiajs/vue3';
import { dashboard } from '@app/routes';
import * as login from '@app/actions/Laravel/Passkeys/Http/Controllers/PasskeyLoginController';
import * as confirmation from '@app/actions/Laravel/Passkeys/Http/Controllers/PasskeyConfirmationController';

export default {
    props: { confirm: Boolean, disabled: Boolean },
    data: () => ({ supported: false, busy: false, error: '', disposed: false }),
    mounted() {
        this.supported = window.isSecureContext && Passkeys.isSupported();
    },
    beforeUnmount() {
        this.disposed = true;
        if (this.busy) Passkeys.cancel();
    },
    methods: {
        async verify() {
            if (this.busy || this.disabled) return;
            this.busy = true;
            this.error = '';
            const routes = this.confirm ? confirmation : login;
            try {
                const response = await Passkeys.verify({
                    routes: {
                        options: routes.index.url(),
                        submit: routes.store.url(),
                    },
                });
                if (!this.disposed)
                    router.visit(response.redirect || dashboard.url());
            } catch (error) {
                if (!this.disposed)
                    this.error =
                        error instanceof UserCancelledError
                            ? 'Darbība atcelta. Varat mēģināt vēlreiz.'
                            : 'Piekļuves atslēgu neizdevās pārbaudīt. Mēģiniet vēlreiz vai izmantojiet paroli.';
            } finally {
                this.busy = false;
            }
        },
    },
};
</script>

<template>
    <div class="text-center mb-3">
        <button
            v-if="supported"
            type="button"
            class="btn btn-primary btn-link"
            :disabled="busy || disabled"
            @click="verify"
        >
            <i class="material-icons" aria-hidden="true">key</i>
            {{
                busy
                    ? 'Pārbauda…'
                    : confirm
                      ? 'Apstiprināt ar piekļuves atslēgu'
                      : 'Ienākt ar piekļuves atslēgu'
            }}
        </button>
        <p v-else class="fg-2">
            Piekļuves atslēgām nepieciešams HTTPS un saderīga pārlūkprogramma.
        </p>
        <p v-if="error" class="text-danger" role="alert">{{ error }}</p>
    </div>
</template>
